def base(target,grip=0,tag='base',rate=.04,qhold=None,nmax=150):
    if qhold is None:qhold=current()[6:13].copy()
    for i in range(nmax):
        obs=current();d=np.asarray(target)-obs[:3]
        if np.max(abs(d))<.003:break
        a=np.zeros(18);a[:2]=d[:2]*min(1,rate/max(1e-9,np.linalg.norm(d[:2])));a[2]=np.clip(d[2],-rate,rate);a[10]=grip
        err=qhold-obs[6:13];a[3:10]=np.clip(err,-.06,.06);a[11:18]=np.clip(3*err,-.4,.4)
        res=logged_send(a,tag+f'_{i:03d}')
        if res.done:return np.asarray(res.meta['proprio']['now'])
    return current()
